    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0.0:
        return 0.0
    return float(math.log1p(v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0.0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for element, fraction in s.get('composition', {}).items():
        r = props.get(element, {}).get('covalent_radius_A')
        if fraction is not None and fraction > 0.0 and r is not None and math.isfinite(r) and r > 0.0:
            total += fraction * r * r * r
            weight += fraction
    if weight <= 0.0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0.0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for element, fraction in s.get('composition', {}).items():
        value = props.get(element, {}).get('valence_electrons')
        if fraction is not None and fraction > 0.0 and value is not None and math.isfinite(value):
            total += fraction * value
            weight += fraction
    if weight <= 0.0:
        return 0.0
    return float(total / (weight * v))

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    for bond in s.get('neighbors', ()):
        i = bond['i']
        j = bond['j']
        d = bond.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0.0 and occ[j] > 0.0:
            nearest[i] = min(nearest[i], d)
    weight = sum(occ[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0.0:
        return 0.0
    mean = sum(occ[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / weight
    if mean <= 0.0:
        return 0.0
    variance = sum(occ[i] * (nearest[i] - mean) ** 2 for i in range(n) if math.isfinite(nearest[i])) / weight
    return float(math.sqrt(max(0.0, variance)) / mean)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(0.0, float(t.get('occupancy', 1.0) or 0.0)) for t in sites]
    nearest = [math.inf] * n
    neighbors = s.get('neighbors', ())
    for bond in neighbors:
        i = bond['i']
        j = bond['j']
        d = bond.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0.0 and occ[j] > 0.0:
            nearest[i] = min(nearest[i], d)
    coordination = [0.0] * n
    for bond in neighbors:
        i = bond['i']
        j = bond['j']
        d = bond.get('distance_A')
        if d is not None and math.isfinite(d) and d > 0.0 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[j]
    weight = sum(occ)
    if weight <= 0.0:
        return 0.0
    return float(sum(occ[i] * coordination[i] for i in range(n)) / weight)
